node --input-type=module -e "
import Ajv from 'ajv';
const ajv = new Ajv({strict: false, validateFormats: false, allErrors: true});
// 1. invalid type keyword under strict:false
try {
  const v = ajv.compile({type: 'object', properties: {location: {type: 'not-a-json-schema-type'}}});
  console.log('compiled OK (no throw)');
} catch (e) { console.log('compile threw:', e.message); }
// 2. missing required
const v1 = ajv.compile({type: 'object', properties: {location: {type: 'string'}}, required: ['location']});
console.log('missing:', JSON.stringify(v1({})));
// 3. wrong type
const v2 = ajv.compile({type: 'object', properties: {ssn: {type: 'string'}}, required: ['ssn']});
console.log('wrongtype:', JSON.stringify(v2({ssn: 123456789})));
// 4. valid + extra property
const v3 = ajv.compile({type: 'object', properties: {location: {type: 'string'}}, required: ['location']});
console.log('extra ok:', v3({location: 'Paris', extra: 'x'}), JSON.stringify(v3.errors));
// 5. enum
const v4 = ajv.compile({type: 'object', properties: {unit: {type: 'string', enum: ['c','f']}}, required: ['unit']});
console.log('enum:', JSON.stringify(v4({unit: 'kelvin'})));
"

